import 'package:flutter/material.dart';
Future<List<String>?> showAssignRolesDialog(BuildContext c,List<String> initial){final roles=['SUPER_ADMIN','MASJID_ADMIN','IMAM','COMMITTEE_MEMBER','MEMBER'];final selected=initial.toSet();return showDialog<List<String>>(context:c,builder:(x)=>StatefulBuilder(builder:(x,set)=>AlertDialog(title:const Text('Assign roles'),content:Column(mainAxisSize:MainAxisSize.min,children:[for(final r in roles)CheckboxListTile(value:selected.contains(r),title:Text(r),onChanged:(v)=>set(()=>v==true?selected.add(r):selected.remove(r)))],),actions:[TextButton(onPressed:()=>Navigator.pop(x),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(x,selected.toList()),child:const Text('Save'))])));}
